def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for index, operation in enumerate(ops):
        tokens = operation.split()
        success = False

        if tokens:
            verb = tokens[0]

            if verb == "open" and len(tokens) == 3:
                _, account, amount = tokens
                if amount.isdigit() and account not in balances:
                    balances[account] = int(amount)
                    history.append(("open", account))
                    success = True

            elif verb == "deposit" and len(tokens) == 3:
                _, account, amount = tokens
                if amount.isdigit() and int(amount) > 0 and account in balances:
                    balances[account] += int(amount)
                    history.append(("balance", account, -int(amount)))
                    success = True

            elif verb == "withdraw" and len(tokens) == 3:
                _, account, amount = tokens
                if amount.isdigit() and int(amount) > 0 and account in balances and account not in frozen and balances[account] >= int(amount):
                    balances[account] -= int(amount)
                    history.append(("balance", account, int(amount)))
                    success = True

            elif verb == "transfer" and len(tokens) == 4:
                _, source, target, amount = tokens
                if (
                    amount.isdigit()
                    and int(amount) > 0
                    and source != target
                    and source in balances
                    and target in balances
                    and source not in frozen
                    and balances[source] >= int(amount)
                ):
                    value = int(amount)
                    balances[source] -= value
                    balances[target] += value
                    history.append(("transfer", source, target, value))
                    success = True

            elif verb in ("freeze", "unfreeze") and len(tokens) == 2:
                account = tokens[1]
                if account in balances and ((verb == "freeze" and account not in frozen) or (verb == "unfreeze" and account in frozen)):
                    was_frozen = account in frozen
                    if verb == "freeze":
                        frozen.add(account)
                    else:
                        frozen.remove(account)
                    history.append(("frozen", account, was_frozen))
                    success = True

            elif verb == "undo" and len(tokens) == 1:
                if history:
                    action = history.pop()
                    kind = action[0]
                    if kind == "open":
                        _, account = action
                        del balances[account]
                        frozen.discard(account)
                    elif kind == "balance":
                        _, account, delta = action
                        balances[account] += delta
                    elif kind == "transfer":
                        _, source, target, value = action
                        balances[source] += value
                        balances[target] -= value
                    elif kind == "frozen":
                        _, account, was_frozen = action
                        if was_frozen:
                            frozen.add(account)
                        else:
                            frozen.discard(account)
                    success = True

        if not success:
            rejected.append(index)

    return balances, rejected
